// Supervisor Photo Report — basic info + site photos only (photo.html).
// Same as the daily report's Prepare Data, minus weather / hazardous work.
const raw = $input.first().json;
const d = raw.body || raw;
// Drop a report this workflow already received (same submissionId — e.g.
// "Resubmit" after the first reply was lost on site). Returning no items stops
// the workflow, so no duplicate PDF / LINE push / Email.
if (d.submissionId) {
  const store = $getWorkflowStaticData('global');
  const seen = store.seenSubmissions || {};
  const now = Date.now();
  for (const id of Object.keys(seen)) if (now - seen[id] > 3 * 24 * 3600 * 1000) delete seen[id]; // keep 3 days
  if (seen[d.submissionId]) return [];
  seen[d.submissionId] = now;
  store.seenSubmissions = seen;
}

// Fill-in time comes from the phone, so the n8n server's time zone never matters
let filledAtLocal = String(d.filledAtLocal || '').trim();
let filledDate = String(d.filledDate || '').trim();
if (!filledAtLocal) {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Bangkok', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
  }).formatToParts(new Date()).map(x => [x.type, x.value]));
  filledAtLocal = `${p.year}/${p.month}/${p.day} ${p.hour}:${p.minute}:${p.second} (Asia/Bangkok, UTC+7)`;
  filledDate = `${p.year}-${p.month}-${p.day}`;
}
const m = filledAtLocal.match(/^(\d{4}\/\d{2}\/\d{2} \d{2}:\d{2})(?::\d{2})?\s*\((?:.*?,\s*)?([^)]*)\)/);
const filledAtShort = m ? `${m[1]} (${m[2]})` : filledAtLocal;
const lateEntry = !!(d.date && filledDate && d.date < filledDate);

const localeMap = { en: 'en-US', th: 'th-TH', zh: 'zh-TW' };
const dateObj = new Date(d.date + 'T00:00:00');
const weekday = dateObj.toLocaleDateString(localeMap[d.language] || 'en-US', { weekday: 'long' });
const weekdayZH = dateObj.toLocaleDateString('zh-TW', { weekday: 'long' });

const safeStr = s => (s || '').slice(0, 30);
// "_photos" keeps it apart from the daily report PDF of the same day
const fileName = `${d.date}_${safeStr(d.contractor)}_${safeStr(d.projectName)}_photos.pdf`;
const photoUrls = d.photoUrls || [];
return [{ json: {
  ...d, submitTime: filledAtShort, filledAtLocal, filledAtShort, filledDate, lateEntry,
  weekday, weekdayZH, fileName, photoUrls, photoCount: photoUrls.length
} }];

// Two PDFs like the daily report: the filler's language + Chinese. There is
// no free text to translate here, so no Gemini step — only the labels differ.
const d = $('Prepare Data').first().json;
const lang = d.language || 'en';
const LBL = {
  en: { title: 'Site Photo Report', projectName: 'Project Name', constructionArea: 'Construction Area', date: 'Date', weekday: 'Day', contractor: 'Contractor', supervisor: 'Engineer', time: 'Filled In', photos: 'Photos', late: 'Late entry', genLabel: 'Filled in' },
  th: { title: 'รายงานรูปภาพหน้างาน', projectName: 'ชื่อโครงการ', constructionArea: 'พื้นที่ก่อสร้าง', date: 'วันที่', weekday: 'วัน', contractor: 'ผู้รับเหมา', supervisor: 'ผู้ควบคุมงาน', time: 'เวลาที่กรอก', photos: 'จำนวนรูป', late: 'บันทึกย้อนหลัง', genLabel: 'กรอกเมื่อ' },
  zh: { title: '現場照片回報', projectName: '工程名稱', constructionArea: '施工廠區', date: '日期', weekday: '星期', contractor: '施工廠商', supervisor: '負責工程師', time: '填寫時間', photos: '照片張數', late: '補填', genLabel: '填寫時間' }
};
const L = LBL[lang] || LBL.en;
const photoUrls = d.photoUrls || [];
const esc = s => String(s || '-').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
let photoHtml = '';
for (let i = 0; i < photoUrls.length; i += 4) {
  const chunk = photoUrls.slice(i, i + 4);
  const cells = chunk.map(url => `<td style='width:50%;padding:4px'><img src='${url}' style='width:100%;height:auto'></td>`);
  while (cells.length < 4) cells.push(`<td style='width:50%;padding:4px'></td>`);
  photoHtml += `<table style='width:100%;border-collapse:collapse;margin-top:8px;page-break-inside:avoid'><tr>${cells.slice(0,2).join('')}</tr><tr>${cells.slice(2,4).join('')}</tr></table>`;
}
function buildHtml(Lb, weekday) {
  const genStamp = d.filledAtShort || '';
  const timeCell = esc(d.filledAtShort) + (d.lateEntry ? ` <b style='color:#a05a00'>(${Lb.late})</b>` : '');
  return `<!DOCTYPE html><html><head><meta charset='UTF-8'><style>body{font-family:Arial,'Noto Sans Thai',sans-serif;font-size:10pt;margin:0}.t{text-align:center;font-weight:bold;margin-bottom:4px}table.m{width:100%;border-collapse:collapse}table.m td{border:1px solid #333;padding:4px 6px;vertical-align:top}.gen-stamp{position:fixed;bottom:6mm;right:8mm;font-size:8pt;color:#aaaaaa}</style></head><body><div class='gen-stamp'>${Lb.genLabel}: ${genStamp}</div><div class='t' style='font-size:14pt'>ECO INFINIC</div><div class='t' style='font-size:12pt;margin-bottom:8px'>${Lb.title}</div><table class='m'><tr><td style='width:12%'><b>${Lb.projectName}</b></td><td style='width:38%'>${esc(d.projectName)}</td><td style='width:12%'><b>${Lb.constructionArea}</b></td><td style='width:38%'>${esc(d.constructionArea)}</td></tr><tr><td><b>${Lb.date}</b></td><td>${esc(d.date)}</td><td><b>${Lb.weekday}</b></td><td>${esc(weekday)}</td></tr><tr><td><b>${Lb.contractor}</b></td><td>${esc(d.contractor)}</td><td><b>${Lb.supervisor}</b></td><td>${esc(d.supervisor)}</td></tr><tr><td><b>${Lb.time}</b></td><td>${timeCell}</td><td><b>${Lb.photos}</b></td><td>${photoUrls.length}</td></tr></table>${photoHtml}</body></html>`;
}
const html = buildHtml(L, d.weekday);
const htmlZH = buildHtml(LBL.zh, d.weekdayZH);
const variants = [
  { lang: 'contractor', html, fileName: d.fileName },
  { lang: 'zh', html: htmlZH, fileName: d.fileName.replace('.pdf', '_ZH.pdf') }
];
return [{ json: { ...d, variants } }];

const items = $input.all();
const prevItems = $('Wait Job').all();
return items.map((it, i) => {
  const prevAttempts = (prevItems[i] && prevItems[i].json.attempts) || 0;
  return { json: { ...it.json, attempts: prevAttempts + 1 } };
});

const items = $input.all();
const isTerminal = j => ['success','failed','aborted'].includes(j.status) || j.attempts >= 20;
const allDone = items.every(it => isTerminal(it.json));
return items.map(it => ({ json: { ...it.json, allDone } }));

// Same LINE / Email as the daily report, minus Notion and the work-detail fields.
const d = $('Prepare Data').first().json;
const variantOrigins = $('Split Out').all();
const driveUploads = $('Google Drive Upload').all();
const idxOf = lang => variantOrigins.findIndex(it => it.json.lang === lang);
const driveUrl = 'https://drive.google.com/file/d/' + driveUploads[idxOf('contractor')].json.id + '/view';
const driveUrlZH = 'https://drive.google.com/file/d/' + driveUploads[idxOf('zh')].json.id + '/view';
const lang = d.language || 'en';
const CL = {
  en: { title: '✅ Site Photos Submitted', date: 'Date', project: 'Project', area: 'Area', photos: 'Photos', download: '📥 Download PDF', share: '📤 Share', shareTitle: 'Site Photo Report', filled: 'Filled in', late: '(late entry)' },
  th: { title: '✅ ส่งรูปภาพหน้างานสำเร็จ', date: 'วันที่', project: 'โครงการ', area: 'พื้นที่', photos: 'จำนวนรูป', download: '📥 ดาวน์โหลด PDF', share: '📤 แชร์', shareTitle: 'รายงานรูปภาพหน้างาน', filled: 'กรอกเมื่อ', late: '(บันทึกย้อนหลัง)' },
  zh: { title: '✅ 現場照片已送出', date: '日期', project: '工程', area: '廠區', photos: '照片', download: '📥 下載 PDF', share: '📤 分享', shareTitle: '現場照片回報', filled: '填寫時間', late: '（補填）' }
};
const cl = CL[lang] || CL.en;
const trunc = (s, n) => String(s || '').trim().substring(0, n) || '-';
function kv(label, value) {
  return { type: 'box', layout: 'horizontal', spacing: 'sm', margin: 'sm', contents: [{ type: 'text', text: label, size: 'xs', color: '#888888', flex: 3, wrap: false }, { type: 'text', text: value, size: 'xs', color: '#333333', flex: 5, wrap: true }] };
}
// "Share" opens LINE's chat picker with a short summary + the PDF link (URI max 1000 chars)
function shareUri(cl, pdfUrl) {
  const head = `📷 ${cl.shareTitle} ${d.date || ''}`;
  const tail = `📥 PDF: ${pdfUrl}`;
  const full = [head, `${cl.project}: ${trunc(d.projectName, 40)}`, String(d.contractor || ''), tail].filter(Boolean).join('\n');
  const uri = 'https://line.me/R/share?text=' + encodeURIComponent(full);
  return uri.length <= 1000 ? uri : 'https://line.me/R/share?text=' + encodeURIComponent(head + '\n' + tail);
}
function buildFlex(cl, weekday, pdfUrl, headerColor, showFilled) {
  const body = [
    kv(cl.date, d.date + ' (' + weekday + ')' + (d.lateEntry ? ' ' + cl.late : '')),
    kv(cl.project, trunc(d.projectName, 50)),
    kv(cl.area, trunc(d.constructionArea, 50)),
    kv(cl.photos, String(d.photoCount)),
    ...(showFilled ? [kv(cl.filled, d.filledAtShort || '-')] : [])
  ];
  // First photo as the bubble image, so the message shows what was sent
  const hero = d.photoUrls && d.photoUrls[0]
    ? { type: 'image', url: d.photoUrls[0], size: 'full', aspectRatio: '4:3', aspectMode: 'cover', action: { type: 'uri', uri: pdfUrl } }
    : undefined;
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: headerColor, paddingAll: '14px', contents: [{ type: 'text', text: cl.title, color: '#ffffff', weight: 'bold', size: 'md', wrap: true }, { type: 'text', text: String(d.contractor || ''), color: '#ffffffcc', size: 'xs', margin: 'xs' }] },
    ...(hero ? { hero } : {}),
    body: { type: 'box', layout: 'vertical', paddingAll: '12px', contents: body },
    footer: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '10px', contents: [
      { type: 'button', style: 'primary', color: headerColor, height: 'sm', action: { type: 'uri', label: cl.download, uri: pdfUrl } },
      { type: 'button', style: 'secondary', height: 'sm', action: { type: 'uri', label: cl.share, uri: shareUri(cl, pdfUrl) } }
    ] }
  };
}
const contractorFlex = { to: d.lineUserId, messages: [{ type: 'flex', altText: cl.title, contents: buildFlex(cl, d.weekday, driveUrl, '#1a73e8', false) }] };
const jerryFlex = { to: 'Ubf65144da2093a2cb9e01528d773413f', messages: [{ type: 'flex', altText: CL.zh.title, contents: buildFlex(CL.zh, d.weekdayZH, driveUrlZH, '#0d7a0d', true) }] };
function escHtml(s) { return String(s || '-').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const JERRY_EMAIL = 'jerry_hsieh@eco-infinic.com';
const recipientEmail = (d.supervisorEmail || '').trim() || JERRY_EMAIL;
const isJerry = recipientEmail.toLowerCase() === JERRY_EMAIL.toLowerCase();
const emailSubject = `現場照片回報 - ${d.projectName || ''} - ${d.date || ''}`;
const emailHtml = `<p><b>${escHtml(d.contractor)}</b> 提交了新的現場照片回報（負責工程師：${escHtml(d.supervisor)}）。</p><p>工程：${escHtml(d.projectName)}<br>廠區：${escHtml(d.constructionArea)}<br>日期：${escHtml(d.date)}（${escHtml(d.weekdayZH)}）${d.lateEntry ? '<b style="color:#a05a00">（補填）</b>' : ''}<br>廠商：${escHtml(d.contractor)}<br>照片：${d.photoCount} 張<br>填寫時間：${escHtml(d.filledAtShort)}</p><p><a href="${driveUrlZH}">📥 下載中文版 PDF</a></p>`;
return [{ json: { contractorPayload: JSON.stringify(contractorFlex), jerryPayload: JSON.stringify(jerryFlex), isJerry, recipientEmail, emailSubject, emailHtml } }];
